let applyingRemote=false,lastRemoteView='';const online=()=>Boolean(window.Room?.active);const myPlayer=()=>online()?window.Room.role:null;const report=e=>{$('#connection-status').textContent=e.message||String(e);};
const C=window.NIGHT_CONTENT,$=s=>document.querySelector(s),KEY='wahala-night-v1';
const fresh=()=>({ready:{shazily:false,anike:false},started:false,done:[],seen:[],slide:0,objections:{shazily:0,anike:0},chat:[],quoteRound:0,quoteAnswers:{},scores:{shazily:0,anike:0},replyRound:0,replyAnswers:{},storyRound:0,storyAnswers:{},softRound:0,softAnswers:{},traps:[],jury:{}});
let S;try{S=JSON.parse(localStorage.getItem(KEY))||fresh();}catch{S=fresh();}S.jury??={};let current='';
const modules=[['quotes','Who said it? 😹','Tap a name. See who remembers your chat.'],['replies','What did I say next? 🌚','Guess the reply. No peeking.'],['traps','You remember me? 👀','Ask your person one cheeky question.'],['opening','Your chat is funny 😂','A little look back. Read it only if you feel like it.'],['stories','Remember that day? 🥹','Share one little memory. A few words will do.'],['soft','Be sweet small ❤️','Say something nice. Don’t be shy now.']];
const name=id=>id==='anike'?'Anike':'Shazily',other=id=>id==='anike'?'shazily':'anike';
function save(){if(online()&&!applyingRemote)window.Room.patch({current,ready:S.ready,done:S.done,seen:S.seen,slide:S.slide,objections:S.objections,quoteRound:S.quoteRound,replyRound:S.replyRound,storyRound:S.storyRound,softRound:S.softRound,started:S.started}).catch(report);localStorage.setItem(KEY,JSON.stringify(S));$('#overall').textContent=S.done.length+' / 6 games';$('#chat-count').textContent=S.chat.length;}
function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function stop(){if('speechSynthesis' in window)speechSynthesis.cancel();}
function page(which){const entering=$('#'+which).hidden;for(const id of ['lobby','hub','experience'])$('#'+id).hidden=id!==which;if(entering)scrollTo(0,0);}
function complete(id){if(!S.done.includes(id)){S.done.push(id);save();}}
function hub(){stop();current='';page('hub');$('#hub-cards').innerHTML=modules.map(([id,title,copy],i)=>`<button class="hub-card ${S.done.includes(id)?'complete':''}" data-module="${id}"><span class="number">0${i+1}</span><span class="status">${S.done.includes(id)?'COMPLETED ✓':progressLabel(id)}</span><h3>${esc(title)}</h3><p>${esc(copy)}</p></button>`).join('');$('#all-done')?.remove();if(S.done.length===6)$('#hub-cards').insertAdjacentHTML('afterend','<p class="toast" id="all-done">You played them all! Go and gist now. ❤️</p>');save();}
function progressLabel(id){const n=id==='opening'?S.seen.length:id==='quotes'?S.quoteRound:id==='replies'?S.replyRound:id==='stories'?S.storyRound:id==='soft'?S.softRound:S.traps.filter(t=>t.finished).length;const total=id==='opening'?15:id==='quotes'?8:id==='traps'?2:4;return n?n+' / '+total+' PLAYED':'NOT STARTED';}
function open(id){stop();current=id;page('experience');$('#section-name').textContent=modules.find(m=>m[0]===id)[1];render();scrollTo(0,0);}
function render(){if(current==='opening')renderSlide();else if(current==='quotes')renderQuotes();else if(current==='traps')renderTraps();else if(current==='replies')renderWritten('reply');else if(current==='stories')renderWritten('story');else renderWritten('soft');protectPlayerControls();save();}

function juryHTML(i){const questions={6:'Who gets jealous more? 🌚',9:'Who’s the star here? 😎',13:'Who brings more wahala? 😹'};if(!questions[i])return '';const a=S.jury[i]||{},both=typeof a.shazily==='string'&&typeof a.anike==='string';return `<div class="jury"><p class="eyebrow">PICK ONE. BE HONEST 🌚</p><h3>${esc(questions[i])}</h3>${(online()?[myPlayer()]:['shazily','anike']).map(id=>`<div class="player-answer"><label>${online()?'Your pick':name(id)+'’s pick'}</label>${a[id]?'<p>Pick sent ✓ Waiting for your person.</p>':`<div class="choices">${['shazily','anike','both'].map(v=>`<button class="choice" data-jury="${i}" data-voter="${id}" data-nominee="${v}">${v==='both'?'Both, obviously':name(v)}</button>`).join('')}</div>`}</div>`).join('')}${both?`<div class="result"><p>Shazily picked: ${a.shazily==='both'?'Both':name(a.shazily)}.</p><p>Anike picked: ${a.anike==='both'?'Both':name(a.anike)}.</p><p>Oya, explain your choice in the gist corner. 😹</p></div>`:''}</div>`;}
function renderSlide(){stop();const i=S.slide,s=C.slides[i];if(!S.seen.includes(i))S.seen.push(i);if(S.seen.length===C.slides.length)complete('opening');$('#section-progress').textContent=(i+1)+' / '+C.slides.length;
$('#stage').innerHTML=`<article class="slide"><p class="eyebrow">${esc(s.tag)}</p><h2>${esc(s.title)}</h2><p class="verdict">${esc(s.verdict)}</p><p class="slide-copy">${esc(s.body)}</p><div class="receipts">${s.receipt.map(t=>`<div class="receipt">${esc(t)}</div>`).join('')}</div>${juryHTML(i)}<details class="count-note"><summary>Where this came from</summary><p class="footnote">${esc(s.foot)}</p></details></article><div class="slide-controls"><div class="control-group"><button data-action="prev" ${i===0?'disabled':''}>← Back</button><button data-action="next">${i===C.slides.length-1?'Pick a game →':'Next →'}</button></div><div class="control-group"><button data-objection="shazily">Shazily: lies! 😹 (${S.objections.shazily})</button><button data-objection="anike">Anike: lies! 😹 (${S.objections.anike})</button></div></div><p class="toast" id="objection-note" role="status"></p><div class="timeline" aria-label="Chat cards">${C.slides.map((_,j)=>`<button data-slide="${j}" class="${S.seen.includes(j)?'seen':''} ${j===i?'current':''}" aria-label="Card ${j+1}" ${j===i?'aria-current="step"':''}></button>`).join('')}</div>`;}

function endCard(id,title){complete(id);$('#section-progress').textContent='Completed';$('#stage').innerHTML=`<div class="completion"><p class="eyebrow">NICE ONE 😹</p><h2>${esc(title)}</h2><p>Try another game whenever you like.</p><button class="primary" data-action="hub">Pick a game →</button> ${online()?'':'<button class="pill" data-action="replay">Play again</button>'}</div>`;}
function renderQuotes(){if(S.quoteRound>=C.quotes.length)return endCard('quotes',S.scores.shazily===S.scores.anike?'It’s a tie. Both of you know the gist. 😹':name(S.scores.shazily>S.scores.anike?'shazily':'anike')+' wins! Oya, small bragging rights. 😹');const q=C.quotes[S.quoteRound],a=S.quoteAnswers[S.quoteRound]||{},both=typeof a.shazily==='string'&&typeof a.anike==='string',players=online()?[myPlayer()]:['shazily','anike'];$('#section-progress').textContent=(S.quoteRound+1)+' / '+C.quotes.length;$('#stage').innerHTML=`<article class="game-card"><p class="eyebrow">WHO SAID IT? 😹</p><h2>Whose mouth is this?</h2><p class="small">Tap a name. We’ll show the answer after both of you guess.</p><blockquote>“${esc(q[0])}”</blockquote>${players.map(id=>`<div class="player-answer"><label>${online()?'Your guess':name(id)+'’s guess'}</label>${a[id]?'<p>Guess sent ✓</p>':`<div class="choices"><button class="choice" data-guess="shazily" data-player="${id}">Shazily</button><button class="choice" data-guess="anike" data-player="${id}">Anike</button></div>`}</div>`).join('')}${online()&&!both?`<p class="partner-wait">${a[other(myPlayer())]?name(other(myPlayer()))+' has guessed ✓':'Waiting for '+name(other(myPlayer()))+' to guess…'}</p>`:''}${both?`<div class="result"><p><b>${name(q[1])}</b> said it! 😹</p><p>${['shazily','anike'].map(id=>name(id)+': '+(a[id]===q[1]?'got it right ✓':'picked '+name(a[id])+' 😹')).join('<br>')}</p></div><button class="primary" data-action="quote-next">${S.quoteRound===C.quotes.length-1?'Who won? →':'Next one →'}</button>`:''}<div class="scores"><span>Shazily: ${S.scores.shazily}</span><span>Anike: ${S.scores.anike}</span></div></article>`;}

const softPrompts=['What small thing do I do that makes you smile?','When did you feel proud of me?','Where should we go together next?','What prayer are you making for me?'];

function renderWritten(type){const field=type+'Round',answers=type+'Answers',r=S[field],total=4;if(r>=total)return endCard(current,type==='soft'?'See you forming hard person. You’re sweet. ❤️':'That was a nice little trip back. 🥹');const item=type==='reply'?C.replies[r]:type==='story'?C.stories[r]:null;const title=type==='reply'?'What did I say next?':type==='story'?item[0]:'Be sweet small. ❤️';const prompt=type==='reply'?item[0]:type==='story'?item[2]:softPrompts[r];const a=S[answers][r]||{},both=typeof a.shazily==='string'&&typeof a.anike==='string';$('#section-progress').textContent=(r+1)+' / 4';$('#stage').innerHTML=`<article class="game-card"><p class="eyebrow">${type==='reply'?'GUESS MY REPLY 🌚':type==='story'?'REMEMBER THIS? 🥹':'SAY IT. DON’T BE SHY ❤️'}</p><h2>${esc(title)}</h2>${type==='story'?`<p class="story-copy">${esc(item[1])}</p>`:''}<blockquote>${esc(prompt)}</blockquote>${(online()?[myPlayer()]:['shazily','anike']).map(id=>`<div class="player-answer"><label>${online()?'Your answer':name(id)+'’s answer'} ${a[id]?'· SENT ✓':''}</label>${a[id]?(both?'<p>Sent ✓</p>':'<p>Sent ✓ Waiting for your person.</p>'):`<form class="written-form" data-player="${id}" data-type="${type}"><label class="sr-only" for="answer-${id}">${name(id)}’s answer</label><textarea id="answer-${id}" name="answer" maxlength="1800" required placeholder="A few words is fine…"></textarea><button class="primary">Send my answer →</button></form>`}</div>`).join('')}${both?`<div class="result"><p><b>Shazily</b><br>${esc(a.shazily).replace(/\n/g,'<br>')}</p><p><b>Anike</b><br>${esc(a.anike).replace(/\n/g,'<br>')}</p>${type==='reply'?`<p><b>What was really said</b><br>${esc(item[1])}</p><p class="small">Who got closer? You two decide. 😹</p>`:''}</div><button class="primary" data-action="written-next" data-type="${type}">${r===3?'Done →':'Next →'}</button>`:'<p class="small">Both of you send an answer. Then you can see them together.</p>'}</article>`;}
function renderTraps(){const finished=S.traps.filter(t=>t.finished).length;$('#section-progress').textContent=finished+' / 2 turns done';if(finished>=2)return endCard('traps','Oya, you know each other small. 😹');const pending=S.traps.find(t=>!t.finished);if(!pending){const available=['shazily','anike'].filter(id=>!S.traps.some(t=>t.author===id));if(online()&&!available.includes(myPlayer())){$('#stage').innerHTML='<article class="game-card"><h2>Your person’s turn 👀</h2><p>Waiting for '+name(other(myPlayer()))+' to send you a question.</p></article>';return;}$('#stage').innerHTML=`<article class="game-card"><p class="eyebrow">${online()?name(myPlayer()).toUpperCase()+' ASKS THEIR PERSON':'ASK YOUR PERSON 👀'}</p><h2>You think I’ve<br>forgotten?</h2><p>Pick a question below or write your own. Add the answer. Your person has to guess it.</p><form id="trap-form" class="stack"><label>Who’s asking? <select name="author">${available.map(id=>`<option value="${id}">${name(id)}</option>`).join('')}</select></label><div class="choices">${(C.prompts[online()?myPlayer():available[0]]||[]).map((q,i)=>`<button type="button" class="pill" data-suggestion="${i}">${esc(q.question)}</button>`).join('')}</div><label>Your question<textarea id="trap-question" name="question" maxlength="1000" required placeholder="What should your person remember? 🌚"></textarea></label><label>The answer<input id="trap-answer" name="answer" maxlength="1000" required></label><label>Will they get it? <select name="prediction"><option value="forget">They’ll miss it 😹</option><option value="remember">They’ll get it ❤️</option></select></label><button class="primary">${online()?'Ask my person →':'Ready? Pass the phone →'}</button></form></article>`;return;}
$('#stage').innerHTML=`<article class="game-card"><p class="eyebrow">${name(pending.author).toUpperCase()} WANTS TO KNOW</p><h2>${name(other(pending.author))},<br>you remember? 👀</h2><div class="question-box">${esc(pending.question)}</div>${!pending.guess?`<form id="trap-guess" class="stack"><label>Your answer<textarea name="guess" maxlength="1000" required></textarea></label><button class="primary">Send my guess →</button></form>`:`<div class="result"><p><b>The guess</b><br>${esc(pending.guess)}</p><p><b>Their answer</b><br>${esc(pending.answer||'Getting the answer…')}</p><p>${name(pending.author)} thought you’d ${pending.prediction==='remember'?'get it ❤️':'miss it 😹'}</p></div><p>${name(pending.author)}, did they get it? Close enough counts. 😹</p><div class="choices"><button class="primary" data-trap-result="remember">Got it ❤️</button><button class="pill" data-trap-result="forget">Not even close 😹</button></div>`}</article>`;}
let chatRoom='',seenMessages=new Set(),chatHistoryLoaded=false,unreadMessages=0,lastChatView='';
function chatUnreadUI(){const badge=$('#chat-unread');badge.hidden=!unreadMessages;badge.textContent=unreadMessages+' new';$('#chat-toggle').setAttribute('aria-label',unreadMessages?'Gist corner, '+unreadMessages+' unread messages':'Gist corner');}
function receiveChat(d){
 if(chatRoom!==d.roomId){chatRoom=d.roomId;seenMessages=new Set();chatHistoryLoaded=false;unreadMessages=0;$('#chat-notice').hidden=true;}
 if(!d.messagesReady)return;
 const incoming=d.messages.filter(m=>!seenMessages.has(m.id)&&m.by!==d.role);
 d.messages.forEach(m=>seenMessages.add(m.id));
 if(chatHistoryLoaded&&incoming.length&&$('#chat-panel').hidden){unreadMessages+=incoming.length;const latest=incoming.at(-1);$('#chat-preview').textContent=name(latest.by)+': '+latest.text;$('#chat-notice').hidden=false;}
 chatHistoryLoaded=true;chatUnreadUI();
}
function chatRender(){const log=$('#chat-messages'),view=JSON.stringify(S.chat);if(view===lastChatView)return;lastChatView=view;const follow=log.scrollHeight-log.scrollTop-log.clientHeight<60;log.innerHTML=S.chat.map(m=>`<div class="chat-message ${m.by}"><b>${name(m.by)}</b>${m.context?`<span class="chat-context">${esc(m.context)}</span>`:''}${esc(m.text).replace(/\n/g,'<br>')}</div>`).join('');if(follow)log.scrollTop=log.scrollHeight;save();}
function contextLabel(){return current==='opening'?'Chat recap · card '+(S.slide+1):current==='quotes'?'Quiz · round '+(S.quoteRound+1):current==='replies'?'Finish my reply · round '+(S.replyRound+1):current==='stories'?'Remember that day · round '+(S.storyRound+1):current==='soft'?'Be sweet small · round '+(S.softRound+1):current==='traps'?'You remember me?':'Our night';}
function addChat(by,text){if(online()){window.Room.chat(text,contextLabel()).catch(report);return;}S.chat.push({by,text,context:contextLabel(),time:Date.now()});if(S.chat.length>150)S.chat.shift();chatRender();}
$('#begin').addEventListener('click',()=>{if(!S.ready.shazily||!S.ready.anike)return;S.started=true;save();open('quotes');});
document.querySelectorAll('[data-ready]').forEach(b=>{b.setAttribute('aria-pressed',String(S.ready[b.dataset.ready]));b.addEventListener('click',()=>{const id=b.dataset.ready;S.ready[id]=!S.ready[id];b.setAttribute('aria-pressed',String(S.ready[id]));readyUI();save();});});
function readyUI(){const ready=S.ready.shazily&&S.ready.anike;$('#begin').disabled=!ready;$('#begin').textContent=ready?'Start playing →':'Waiting for both players to be ready';const next=$('#room-next');next.hidden=!online();if(online()){const me=myPlayer(),partner=other(me),mine=S.ready[me];$('#room-ready').textContent=mine?'Ready ✓ — undo':'I’m ready — let’s play →';$('#room-ready').setAttribute('aria-pressed',String(mine));$('#room-next-step').textContent=!mine?'Next: tap “I’m ready”, then ask '+name(partner)+' to do the same on their phone.':!S.ready[partner]?'You’re ready. Waiting for '+name(partner)+' to join and tap “I’m ready”. The game starts automatically when both of you are ready.':'Both ready. Let’s play! 😹';}document.querySelectorAll('[data-ready]').forEach(b=>{const id=b.dataset.ready;b.textContent=S.ready[id]?'Ready ✓ — undo':'I’m ready as '+name(id);b.setAttribute('aria-pressed',String(S.ready[id]));});}readyUI();$('#resume').hidden=!S.started;
$('#room-ready').addEventListener('click',()=>{if(online())document.querySelector('[data-ready="'+myPlayer()+'"]').click();});
$('#resume').addEventListener('click',hub);$('#home').addEventListener('click',e=>{e.preventDefault();S.started?hub():page('lobby');});$('#back-hub').addEventListener('click',hub);
$('#reset').addEventListener('click',()=>{if(online()){report(new Error('Create a new room to start a fresh online night. The existing room is kept.'));return;}if(!confirm('Clear this phone’s answers and start again?'))return;stop();S=fresh();save();location.reload();});
document.addEventListener('click',e=>{const suggestion=e.target.closest('[data-suggestion]');if(suggestion){const author=online()?myPlayer():document.querySelector('[name=author]').value,q=C.prompts[author][Number(suggestion.dataset.suggestion)];document.querySelector('[name=question]').value=q.question;document.querySelector('[name=answer]').value=q.answer;}const ballot=e.target.closest('[data-jury]');if(ballot){if(online()){window.Room.submit('jury-'+S.slide,'jury',ballot.dataset.nominee).catch(report);return;}const i=ballot.dataset.jury;S.jury[i]??={};S.jury[i][ballot.dataset.voter]=ballot.dataset.nominee;renderSlide();save();}const m=e.target.closest('[data-module]');if(m)open(m.dataset.module);const slide=e.target.closest('[data-slide]');if(slide){if(online()){window.Room.playback({slide:Number(slide.dataset.slide)}).catch(report);return;}S.slide=Number(slide.dataset.slide);render();}const o=e.target.closest('[data-objection]');if(o){const id=o.dataset.objection;S.objections[id]++;o.textContent=name(id)+': lies! 😹 ('+S.objections[id]+')';$('#objection-note').textContent=name(id)+', we heard you. The chat still says what it says. 😹';addChat(id,'Lies! 😹 Card '+(S.slide+1)+' is dragging me. Let me explain. 😹');save();}const g=e.target.closest('[data-guess]');if(g){if(online()){window.Room.submit('quote-'+S.quoteRound,'quote',g.dataset.guess).catch(report);return;}const r=S.quoteRound;S.quoteAnswers[r]??={};if(S.quoteAnswers[r][g.dataset.player])return;S.quoteAnswers[r][g.dataset.player]=g.dataset.guess;if(g.dataset.guess===C.quotes[r][1])S.scores[g.dataset.player]++;render();}const tr=e.target.closest('[data-trap-result]');if(tr){if(online()){const t=S.traps.find(t=>!t.finished);window.Room.grade(t.author,tr.dataset.trapResult).catch(report);return;}const t=S.traps.find(t=>!t.finished);t.finished=true;t.result=tr.dataset.trapResult;render();}const a=e.target.closest('[data-action]')?.dataset.action;if(a==='hub')hub();if(a==='prev'){if(online()){window.Room.playback({slide:Math.max(0,S.slide-1)}).catch(report);return;}S.slide=Math.max(0,S.slide-1);render();}if(a==='next'){if(online()&&S.slide<14){window.Room.playback({slide:S.slide+1}).catch(report);return;}if(S.slide===14)hub();else{S.slide++;render();}}if(a==='quote-next'){if(online()){window.Room.nextRound('quote',S.quoteRound).catch(report);return;}S.quoteRound++;render();}if(a==='written-next'){const type=e.target.dataset.type;if(online()){window.Room.nextRound(type,S[type+'Round']).catch(report);return;}S[type+'Round']++;render();}if(a==='replay'){if(online()){report(new Error('Your answers are saved here. Make a new room to play again.'));return;}if(current==='quotes'){S.quoteRound=0;S.quoteAnswers={};S.scores={shazily:0,anike:0};}if(current==='replies'){S.replyRound=0;S.replyAnswers={};}if(current==='stories'){S.storyRound=0;S.storyAnswers={};}if(current==='soft'){S.softRound=0;S.softAnswers={};}if(current==='traps')S.traps=[];render();}if(e.target.closest('[data-close]'))e.target.closest('dialog').close();});
document.addEventListener('submit',e=>{if(e.target.matches('.written-form')){e.preventDefault();const f=e.target,t=f.dataset.type,r=S[t+'Round'],value=new FormData(f).get('answer').trim();if(!value)return;if(online()){window.Room.submit(t+'-'+r,t,value).catch(report);return;}S[t+'Answers'][r]??={};S[t+'Answers'][r][f.dataset.player]=value;render();}if(e.target.id==='trap-form'){e.preventDefault();const f=new FormData(e.target),question=f.get('question').trim(),answer=f.get('answer').trim();if(!question||!answer)return;if(online()){window.Room.question(question,answer,f.get('prediction')).catch(report);return;}S.traps.push({author:f.get('author'),question,answer,prediction:f.get('prediction'),finished:false});render();}if(e.target.id==='trap-guess'){e.preventDefault();const value=new FormData(e.target).get('guess').trim();if(!value)return;if(online()){const t=S.traps.find(t=>!t.finished);window.Room.submit('trap-'+t.author,'trap',value).catch(report);return;}S.traps.find(t=>!t.finished).guess=value;render();}});
function chatToggle(open){$('#chat-panel').hidden=!open;$('#chat-toggle').setAttribute('aria-expanded',String(open));if(open){unreadMessages=0;chatUnreadUI();$('#chat-notice').hidden=true;chatRender();$('#chat-messages').scrollTop=$('#chat-messages').scrollHeight;$('#chat-input').focus();}}$('#chat-toggle').addEventListener('click',()=>chatToggle($('#chat-panel').hidden));$('#chat-close').addEventListener('click',()=>chatToggle(false));$('#chat-notice-open').addEventListener('click',()=>chatToggle(true));$('#chat-form').addEventListener('submit',e=>{e.preventDefault();const input=$('#chat-input'),text=input.value.trim();if(!text)return;addChat($('#chat-speaker').value,text);input.value='';});
$('#method-open').addEventListener('click',()=>{const m=C.method;$('#method-body').innerHTML=`<p>${esc(m.period)}. Anike: ${m.textMessages.anike.toLocaleString()} texts. Shazily: ${m.textMessages.shazily.toLocaleString()} texts.</p><p>${esc(m.definition)}</p><table><thead><tr><th>Message contains</th><th>Anike</th><th>Shazily</th></tr></thead><tbody>${Object.entries(m.matches).map(([k,v])=>`<tr><td>${esc(v.pattern)}</td><td>${v.anike}</td><td>${v.shazily}</td></tr>`).join('')}</tbody></table><p class="small">The numbers come from your chat. The jokes are just jokes. You two know each other best.</p>`;$('#method-dialog').showModal();});
save();chatRender();

function protectPlayerControls(){if(!online())return;const me=myPlayer();for(const selector of ['#create-room','#join-room','#local-mode','.ready-grid','#begin'])$(selector).hidden=true;$('#join-code').closest('label').hidden=true;document.querySelectorAll('[data-player],[data-voter],[data-objection]').forEach(b=>{const who=b.dataset.player||b.dataset.voter||b.dataset.objection;if(who!==me){if(b.tagName==='FORM')b.innerHTML='<p class="small">Waiting for '+name(who)+' to send their answer.</p>';else b.disabled=true;}});document.querySelectorAll('[data-ready]').forEach(b=>{b.disabled=b.dataset.ready!==me;b.setAttribute('aria-pressed',String(S.ready[b.dataset.ready]));});const author=document.querySelector('[name="author"]');if(author){for(const o of author.options)o.disabled=o.value!==me;author.value=me;}const t=S.traps.find(t=>!t.finished);if(t&&t.author===me&&document.querySelector('#trap-guess'))document.querySelector('#trap-guess').innerHTML='<p class="small">Waiting for '+name(other(me))+' to answer.</p>';if(t&&t.author!==me)document.querySelectorAll('[data-trap-result]').forEach(b=>b.disabled=true);$('#chat-speaker').value=me;$('#chat-speaker').disabled=true;}
window.addEventListener('roomerror',e=>report(new Error(e.detail)));
window.addEventListener('roomstate',e=>{const d=e.detail;if(!d.state)return;applyingRemote=true;const view=JSON.stringify({state:d.state,rounds:d.rounds,answers:d.answers,secrets:d.secrets,questions:d.questions});const changed=view!==lastRemoteView;lastRemoteView=view;Object.assign(S,structuredClone(d.state));S.jury={};S.quoteAnswers={};S.replyAnswers={};S.storyAnswers={};S.softAnswers={};S.scores={shazily:0,anike:0};for(const [round,info]of Object.entries(d.rounds)){const values={};for(const role of ['shazily','anike'])if(info.locked?.[role])values[role]=d.answers[round]?.[role]??true;const [kind,index]=round.split('-');const target={jury:'jury',quote:'quoteAnswers',reply:'replyAnswers',story:'storyAnswers',soft:'softAnswers'}[kind];if(target)S[target][index]=values;if(kind==='quote'&&typeof values.shazily==='string'&&typeof values.anike==='string')for(const role of ['shazily','anike'])if(values[role]===C.quotes[Number(index)][1])S.scores[role]++;}S.traps=Object.entries(d.questions).map(([author,q])=>({...q,author,answer:d.secrets['trap-'+author],guess:d.answers['trap-'+author]?.[other(author)]}));S.chat=d.messages;receiveChat(d);const connected=Boolean(d.members?.shazily&&d.members?.anike);$('#connection-status').textContent=connected?'Both connected. This night is shared.':'Connected as '+name(d.role)+'. Waiting for your person to join.';$('#invitation').hidden=false;$('#invite-link').value=window.Room.invite();$('#room-role').value=d.role;$('#room-role').disabled=true;readyUI();protectPlayerControls();const drafts={};document.querySelectorAll('textarea,input').forEach(el=>{if(el.id&&el.value)drafts[el.id]=el.value;});if(changed){stop();current=d.state.current;if(d.state.started){page(current?'experience':'hub');if(current){$('#section-name').textContent=modules.find(m=>m[0]===current)[1];render();}else hub();}else page('lobby');for(const[id,value]of Object.entries(drafts)){const el=document.getElementById(id);if(el&&!el.readOnly)el.value=value;}protectPlayerControls();}chatRender();save();applyingRemote=false;});
async function backend(){if(window.Room)return window.Room;await new Promise((resolve,reject)=>{window.addEventListener('roomavailable',resolve,{once:true});setTimeout(()=>reject(new Error('The connection is still loading. Please try again.')),12000);});return window.Room;}
$('#create-room').addEventListener('click',async()=>{const b=$('#create-room');b.disabled=true;try{const r=await backend();await r.create($('#room-role').value);$('#connection-status').textContent='Room created. Send the invitation to your person.';}catch(e){report(e);}finally{b.disabled=false;}});
async function joinRoom(value){let id=value.trim();try{if(id.includes('://'))id=new URL(id).searchParams.get('room')||'';await(await backend()).join(id);}catch(e){report(e);}}
$('#join-room').addEventListener('click',()=>joinRoom($('#join-code').value));$('#copy-invite').addEventListener('click',async()=>{try{await navigator.clipboard.writeText($('#invite-link').value);$('#copy-invite').textContent='Copied';}catch{$('#invite-link').select();}});$('#local-mode').addEventListener('click',()=>{if(online()){report(new Error('Open a new tab without an invitation to rehearse locally.'));return;}$('#connection-status').textContent='Playing together on one phone. Tap both ready buttons below.';document.querySelector('.ready-grid').scrollIntoView({behavior:'smooth'});});
const incomingRoom=new URLSearchParams(location.search).get('room');if(incomingRoom){$('#join-code').value=incomingRoom;joinRoom(incomingRoom);}
